// ── CFG for arithmetic expressions (informal) ───────────────────
// E → E '+' T | E '-' T | T
// T → T '*' F | T '/' F | F
// F → '(' E ')' | number
//
// This grammar is left-recursive (E → E '+' T) which LL parsers can't
// handle directly, but LR parsers handle fine.
//
// We implement a recursive-descent parser (right-recursive variant)
// that directly mirrors the grammar structure:

function parseExpr(tokens, pos = { i: 0 }) {
  let left = parseTerm(tokens, pos);
  while (tokens[pos.i] === '+' || tokens[pos.i] === '-') {
    const op = tokens[pos.i++];
    const right = parseTerm(tokens, pos);
    left = { op, left, right };
  }
  return left;
}

function parseTerm(tokens, pos) {
  let left = parseFactor(tokens, pos);
  while (tokens[pos.i] === '*' || tokens[pos.i] === '/') {
    const op = tokens[pos.i++];
    const right = parseFactor(tokens, pos);
    left = { op, left, right };
  }
  return left;
}

function parseFactor(tokens, pos) {
  if (tokens[pos.i] === '(') {
    pos.i++; // consume '('
    const node = parseExpr(tokens, pos);
    pos.i++; // consume ')'
    return node;
  }
  return { num: Number(tokens[pos.i++]) };
}

function evaluate(node) {
  if ('num' in node) return node.num;
  const l = evaluate(node.left), r = evaluate(node.right);
  if (node.op === '+') return l + r;
  if (node.op === '-') return l - r;
  if (node.op === '*') return l * r;
  if (node.op === '/') return l / r;
}

// Tokenise a simple expression string
function tokenise(src) {
  return src.replace(/([+\-*/()])/g, ' $1 ').trim().split(/\s+/);
}

const tokens = tokenise('3 + 4 * ( 2 - 1 )');
const ast    = parseExpr(tokens);
console.log(evaluate(ast)); // 7  (not 14 — * binds tighter than +)

// ── Balanced brackets PDA (stack simulation) ────────────────────
function isBalanced(s) {
  const stack = [];
  const pairs = { ')': '(', ']': '[', '}': '{' };
  for (const ch of s) {
    if ('([{'.includes(ch)) { stack.push(ch); }
    else if (')]}'.includes(ch)) {
      if (stack.pop() !== pairs[ch]) return false;
    }
  }
  return stack.length === 0;
}
console.log(isBalanced('({[]})'));  // true
console.log(isBalanced('([)]'));    // false
console.log(isBalanced('{[}'));     // false

// ── Grammar ambiguity ───────────────────────────────────────────
// Ambiguous grammar for expressions:
//   E → E '+' E | E '*' E | '(' E ')' | number
//
// The string '1 + 2 * 3' has TWO parse trees:
//   Tree A: (1 + 2) * 3  => E = (E+E) with E = (E*E)
//   Tree B: 1 + (2 * 3)  => E = (E+E) with right E = (E*E)  [correct meaning]
//
// Ambiguity is bad: the parser must pick one, and might pick the wrong one.
// Fix: rewrite grammar with precedence levels (E→T→F structure above).

// ── Chomsky Normal Form (CNF) ────────────────────────────────────
// Every CFG can be converted to CNF:
//   A → B C   (two non-terminals only)
//   A → a     (one terminal only)
// This enables CYK parsing: O(n^3) for arbitrary CFG in CNF.
// Recursive descent is O(n) for unambiguous LL(1) grammars.

// ── What CFGs cannot do (not context-free) ──────────────────────
// {a^n b^n c^n}          — requires synchronising 3 counts
// {ww | w ∈ {a,b}*}      — copy language; no stack can compare two halves
// These need context-sensitive grammars or full Turing machines.
console.log('CFG = PDA; handles balanced nesting, not simultaneous multi-counting.');
